sys_script_include.script:
var ChargeLine = Class.create();
ChargeLine.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	/**
     * Reference Qualifier for 'invoice' field on Charge Line table.
     * Condition: 
     * - Matches current charge line's patient (`invoice.patient = current.patient`).
     * - Matches current charge line's hospital (`invoice.hospital = current.hospital`).
     * - Only open invoices (status = draft OR status = partially_paid).
     */
    getInvoiceRefQual: function(current) {
        if (!current) return '';

        var currentPatient = current.getValue('patient');
        var currentHospital = current.getValue('hospital');

        // Agar patient ya hospital select nahi hai, toh koi invoice show mat karo
        if (!currentPatient || !currentHospital) {
            return 'sys_id=00000000000000000000000000000000';
        }

        var invoiceSysids = [];
        var invoiceGr = new GlideRecord('x_2223823_apollo_0_invoice'); 
        invoiceGr.addQuery('patient', currentPatient);
        invoiceGr.addQuery('hospital', currentHospital);

        // Open invoices condition (draft OR partially_paid)
        var statusQC = invoiceGr.addQuery('status', 'draft');
        statusQC.addOrCondition('status', 'partially_paid');
		statusQC.addOrCondition('status', 'issued');

        invoiceGr.query();

        while (invoiceGr.next()) {
            invoiceSysids.push(invoiceGr.getUniqueValue());
        }

        // Final Encoded Query return karo
        if (invoiceSysids.length > 0) {
            return 'sys_idIN' + invoiceSysids.join(',');
        } else {
            // Agar koi matching open invoice nahi mili
            return 'sys_id=00000000000000000000000000000000';
        }
    },

    type: 'ChargeLine'
});
